#!/bin/bash
# Prints the three most frequent IP addresses in access.log (first field),
# one per line, most frequent first. Ties are broken by first appearance
# in the log.
set -eu
cd "$(dirname "$0")"

awk '
{
    ip = $1
    count[ip]++
    if (!(ip in first)) {
        first[ip] = NR
        order[++n] = ip
    }
}
END {
    for (i = 1; i <= 3 && i <= n; i++) {
        # selection among remaining: highest count, then earliest first appearance
        best = -1
        for (j = 1; j <= n; j++) {
            if (used[j]) continue
            if (best == -1 ||
                count[order[j]] > count[order[best]] ||
                (count[order[j]] == count[order[best]] && first[order[j]] < first[order[best]])) {
                best = j
            }
        }
        if (best == -1) break
        used[best] = 1
        print order[best]
    }
}
' access.log
